/usr/local/bin/python -c def longest_unique_substring(s: str) -> int:
    if not s:
        return 0
    n = len(s)
    if n == 0:
        return 0
    from collections import Counter
    char_counts = Counter(s)
    max_len = 0
    for char, count in char_counts.items():
        if count == 1:
            max_len = max(max_len, 1)
        else:
            left, right = (0, 0)
            while right < n:
                if s[left:right].count(char) == 1:
                    if len(s[left:right]) > max_len:
                        max_len = len(s[left:right])
                    right += 1
                else:
                    left += 1
    return max_len
assert longest_unique_substring('')==0
assert longest_unique_substring('abba')==2
assert longest_unique_substring('abcabcbb')==3
assert longest_unique_substring('pwwkew')==3
assert longest_unique_substring('tmmzuxt')==5
assert longest_unique_substring('dvdf')==3
